// ValidateTraceEvent validates all fields in TraceEvent according to their annotations.
// Returns a BlueErr if validation fails, or nil if all validations pass.
func ValidateTraceEvent(m *TraceEvent) error {
	return ValidateTraceEventWithDepth(m, 0)
}

// ValidateTraceEventWithDepth validates TraceEvent and carries nested-message depth across
// generated package boundaries.
func ValidateTraceEventWithDepth(m *TraceEvent, depth int) error {
	if m == nil {
		return nil
	}
	if depth > 24 {
		return protoerrors.NewErrMissingInvalidData(nil, "message nesting exceeds max depth of 24")
	}

	// Validate TraceId (assert_max_length: 64)
	if len(m.TraceId) > 64 {
		return protoerrors.NewErrMissingInvalidData(nil, "field TraceId must be at most 64 characters, got: %d", len(m.TraceId))
	}

	// Validate TraceId (assert_required)
	if m.TraceId == "" {
		return protoerrors.NewErrMissingInvalidData(nil, "field TraceId is required")
	}

	// Validate Round (assert_required)
	if m.Round == nil {
		return protoerrors.NewErrMissingInvalidData(nil, "field Round is required")
	}

	// Validate Error (assert_max_length: 512)
	if len(m.Error) > 512 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Error must be at most 512 characters, got: %d", len(m.Error))
	}

	// Validate TraceId (default max size: 32768 bytes)
	if len(m.TraceId) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field TraceId exceeds max size of 32768 bytes, got: %d", len(m.TraceId))
	}

	// Validate Error (default max size: 32768 bytes)
	if len(m.Error) > 32768 {
		return protoerrors.NewErrMissingInvalidData(nil, "field Error exceeds max size of 32768 bytes, got: %d", len(m.Error))
	}

	// Validate Kind enum value is known
	if _, ok := TraceEventKind_name[int32(m.Kind)]; !ok {
		return protoerrors.NewErrMissingInvalidData(nil, "field Kind has unknown enum value %d", int32(m.Kind))
	}

	// Validate Round nested message
	if m.Round != nil {
		if err := ValidateTraceRoundWithDepth(m.Round, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field Round validation failed")
		}
	}

	// Validate Rpc nested message
	if m.Rpc != nil {
		if err := accounting_method.ValidateAccountingMethodWithDepth(m.Rpc, depth+1); err != nil {
			return protoerrors.NewErrMissingInvalidData(err, "field Rpc validation failed")
		}
	}

	return nil
}

