// Merge: TraceRequest
// ============================================================
// MergeTraceRequest fills zero-valued fields in dst from src.
func MergeTraceRequest(dst, src *TraceRequest) {
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if !dst.Noop {
		dst.Noop = src.Noop
	}
}

// ============================================================
// Merge: TraceEvent
// ============================================================
// MergeTraceEvent fills zero-valued fields in dst from src.
func MergeTraceEvent(dst, src *TraceEvent) {
	if dst.TraceId == "" {
		dst.TraceId = src.TraceId
	}
	if dst.Round == nil {
		dst.Round = src.Round
	} else if src.Round != nil {
		MergeTraceRound(dst.Round, src.Round)
	}
	if dst.Rpc == nil {
		dst.Rpc = src.Rpc
	}
	if dst.Kind == 0 {
		dst.Kind = src.Kind
	}
	if dst.Error == "" {
		dst.Error = src.Error
	}
}
